package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;import java.io.*;import java.util.*;
public final class ReconnectChecks {
 static int n;static void ok(boolean b){n++;if(!b)throw new AssertionError("reconnect check "+n);}interface Work{void run()throws Exception;}static void rejects(Work w)throws Exception{boolean rejected=false;try{w.run();}catch(IOException|IllegalArgumentException e){rejected=true;}ok(rejected);}
 public static int run(Context c)throws Exception{n=0;String key="1".repeat(64),other="2".repeat(64),id="a".repeat(64);JSONObject row=new JSONObject().put("id",id).put("kind","Gemini").put("message","synthetic saved answer").put("requestId",key).put("time",10);
 JSONObject first=ImportedAnswers.accept(c,row);ok(first.getBoolean("ok"));ok(!first.optBoolean("duplicate"));ok(ImportedAnswers.accept(c,row).getBoolean("duplicate"));ok(ImportedAnswers.accept(c,new JSONObject(row.toString()).put("time",20)).getBoolean("duplicate"));ok(ImportedAnswers.received(c,key));ok(!ImportedAnswers.received(c,other));ok(!new String(ConversationWorkspace.file(c,"answer-imports").readFully(),"UTF-8").contains("synthetic saved answer"));rejects(()->ImportedAnswers.accept(c,new JSONObject(row.toString()).put("message","different")));rejects(()->ImportedAnswers.accept(c,new JSONObject(row.toString()).put("id","not-id")));rejects(()->ImportedAnswers.accept(c,new JSONObject(row.toString()).put("kind","command")));rejects(()->ImportedAnswers.accept(c,new JSONObject(row.toString()).put("message","x".repeat(64001))));
 ok(ImportedAnswers.merge(c,new ArrayList<>()).size()==1);HashSet<String> keys=new HashSet<>();keys.add(key);ok(ImportedAnswers.hide(c,keys,new HashSet<>())==1);ok(ImportedAnswers.merge(c,new ArrayList<>()).isEmpty());ok(ImportedAnswers.accept(c,row).getBoolean("duplicate"));ok(ImportedAnswers.merge(c,new ArrayList<>()).isEmpty());ok(!ImportedAnswers.received(c,key));
 ok(ConversationCollections.group(new JSONArray().put(new JSONObject(row.toString()).put("legacy",true))).getJSONObject(0).getJSONArray("rows").getJSONObject(0).getBoolean("legacy"));
 JSONObject user=new JSONObject(row.toString()).put("id","b".repeat(64)).put("kind","ユーザー").put("requestId",other);ImportedAnswers.accept(c,user);ok(!ImportedAnswers.received(c,other));JSONObject legacy=new JSONObject(row.toString()).put("id","c".repeat(64)).put("requestId","").put("legacy",true);ImportedAnswers.accept(c,legacy);ArrayList<JSONObject> existing=new ArrayList<>();existing.add(row);ok(ImportedAnswers.merge(c,existing).size()==2);
 JSONObject failed=new JSONObject().put("requestState","FAILED").put("receiptReason","NETWORK");ok(QuestionDelivery.describe(failed,false).contains("AI通信で失敗"));ok(QuestionDelivery.describe(failed,true).contains("回答受信済み"));ok(QuestionDelivery.describe(new JSONObject().put("requestState","ANSWERED"),false).contains("本文受信は未確認"));ok(QuestionDelivery.describe(new JSONObject().put("requestState","QUEUED"),false).contains("断定はできません"));ok(QuestionDelivery.describe(new JSONObject().put("requestState","RUNNING"),false).contains("再送は控えて"));ok(QuestionDelivery.describe(new JSONObject().put("requestState","FAILED").put("receiptReason","AUTH"),false).contains("認証"));
 ok(ReconnectReview.gap(-1,100));ok(!ReconnectReview.gap(100,15099));ok(ReconnectReview.gap(100,15100));ok(ReconnectReview.gap(100,50));ReconnectReview.prefs(c).edit().clear().commit();ReconnectReview.last=-1;ReconnectReview.ever=false;JSONArray order=new JSONArray().put(new JSONObject().put("id",key));ReconnectReview.contact(c,100,order);ok(ReconnectReview.held(c,key));ok(ReconnectReview.prefs(c).getLong("returnedAt",0)>0);ReconnectReview.contact(c,200,new JSONArray().put(new JSONObject().put("id",key)).put(new JSONObject().put("id",other)));ok(!ReconnectReview.held(c,other));ReconnectReview.contact(c,16000,new JSONArray().put(new JSONObject().put("id",key)).put(new JSONObject().put("id",other)));ok(ReconnectReview.held(c,other));rejects(()->ReconnectReview.approve(c,"bad"));rejects(()->ReconnectReview.approve(c,key));
 JSONObject runtime=new JSONObject().put("reconnect",new JSONObject().put("held",new JSONArray().put(key)));JSONObject queued=new JSONObject().put("tracked",true).put("key",key).put("requestState","QUEUED");ok(ConversationWait.reason(queued,new JSONArray().put(queued),runtime,0).contains("内容確認待ち"));
 // Real queue remains unchanged on holding and only the selected ID is released.
 c.getSharedPreferences("phone_secretary",0).edit().putString("pending_command_queue",new JSONArray().put(TrackedWebRequest.wire(key,"synthetic queued")).put(TrackedWebRequest.wire(other,"other queued")).toString()).commit();ok(MainActivity.hasQueuedWebCommand(c,key));ok(ReconnectReview.status(c).getJSONArray("held").length()==2);ReconnectReview.approve(c,key);ok(!ReconnectReview.held(c,key));ok(ReconnectReview.held(c,other));ok(MainActivity.hasQueuedWebCommand(c,key));rejects(()->ReconnectReview.approve(c,key));
 // A short disconnect does not hold a freshly submitted request. Old/unknown times remain held.
 ok(ReconnectReview.recent(1000,120999));ok(!ReconnectReview.recent(1000,121000));ok(!ReconnectReview.recent(0,1000));ok(!ReconnectReview.recent(1001,1000));
 ReconnectReview.prefs(c).edit().clear().commit();ReconnectReview.last=-1;ReconnectReview.ever=false;
 long wall=System.currentTimeMillis();JSONArray times=new JSONArray().put(new JSONObject().put("key",key).put("time",wall-180000)).put(new JSONObject().put("key",other).put("time",wall));c.getSharedPreferences("loki_web_console",0).edit().putString("outbox",times.toString()).commit();
 JSONArray both=new JSONArray().put(new JSONObject().put("id",key)).put(new JSONObject().put("id",other));ReconnectReview.contact(c,100,both);ok(ReconnectReview.held(c,key));ok(!ReconnectReview.held(c,other));
 java.util.ArrayList<String> queue=new java.util.ArrayList<>();queue.add(TrackedWebRequest.wire(key,"held old"));queue.add(TrackedWebRequest.wire(other,"fresh next"));ok(ReconnectReview.dispatchIndex(c,queue)==1);
 c.getSharedPreferences("phone_secretary",0).edit().putString("pending_command_queue",new JSONArray(queue).toString()).commit();ok(!MainActivity.ackTrackedWebCommand(c,key));ok(MainActivity.ackTrackedWebCommand(c,other));ok(MainActivity.hasQueuedWebCommand(c,key));ok(!MainActivity.hasQueuedWebCommand(c,other));ok(!MainActivity.ackTrackedWebCommand(c,other));
 ReconnectReview.approve(c,key);ok(!ReconnectReview.held(c,key));ReconnectReview.contact(c,16100,new JSONArray().put(new JSONObject().put("id",key)));ok(!ReconnectReview.held(c,key));
 ReconnectReview.last=-1;ReconnectReview.ever=false;ReconnectReview.contact(c,100,new JSONArray().put(new JSONObject().put("id",key)));ok(!ReconnectReview.held(c,key));ok(MainActivity.ackTrackedWebCommand(c,key));
 ReconnectReview.contact(c,200,new JSONArray());ok(new JSONArray(ReconnectReview.prefs(c).getString("approved","[]")).length()==0);
 // An old held question does not leak via legacy acknowledgement; legacy head is still FIFO.
 ReconnectReview.prefs(c).edit().putString("held",new JSONArray().put(key).toString()).commit();queue.clear();queue.add(TrackedWebRequest.wire(key,"held"));queue.add("legacy-control");ok(ReconnectReview.dispatchIndex(c,queue)==-1);queue.add(TrackedWebRequest.wire(other,"new"));ok(ReconnectReview.dispatchIndex(c,queue)==2);queue.clear();queue.add("legacy-control");queue.add(TrackedWebRequest.wire(other,"new"));ok(ReconnectReview.dispatchIndex(c,queue)==0);
 ReconnectReview.prefs(c).edit().clear().commit();ReconnectReview.last=-1;ReconnectReview.ever=false;c.getSharedPreferences("phone_secretary",0).edit().clear().commit();c.getSharedPreferences("loki_web_console",0).edit().clear().commit();return n+com.example.rokidkeyboardbridge.AnswerOutboxChecks.run(c);}
}
